INSERT INTO "riddles" (id, subject_id, answer, clue_1, clue_2, clue_3, clue_4, clue_5, difficulty, created_at) VALUES
('riddle_001', 'subj_nsmq_math', 'Pi (π)', 'I am a number that never ends and never repeats', 'I am the ratio of a circle''s circumference to its diameter', 'My first digits are 3.14159...', 'I am named after a Greek letter', 'I am approximately 22/7', 'medium', '2026-08-04T00:00:00.000Z'),
('riddle_002', 'subj_nsmq_physics', 'Black hole', 'I am a region in space from which nothing can escape', 'I am formed when massive stars collapse', 'Light cannot escape my grasp', 'I have an event horizon', 'Stephen Hawking studied me extensively', 'medium', '2026-08-04T00:00:00.000Z'),
('riddle_003', 'subj_nsmq_chemistry', 'Oxygen', 'I am essential for combustion', 'I make up about 21% of Earth''s atmosphere', 'I was discovered by Joseph Priestley', 'I am produced by photosynthesis', 'My atomic number is 8', 'easy', '2026-08-04T00:00:00.000Z'),
('riddle_004', 'subj_nsmq_biology', 'DNA', 'I am a double helix', 'I carry genetic information', 'Watson and Crick discovered my structure', 'I am found in the nucleus of cells', 'I am made of nucleotides containing A, T, G, and C', 'easy', '2026-08-04T00:00:00.000Z'),
('riddle_005', 'subj_nsmq_math', 'Zero', 'I am neither positive nor negative', 'I am the additive identity', 'Any number multiplied by me gives me', 'I was invented in ancient India', 'Division by me is undefined', 'easy', '2026-08-04T00:00:00.000Z'),
('riddle_006', 'subj_nsmq_physics', 'Gravity', 'I am one of the four fundamental forces', 'I am the weakest of these forces', 'I keep planets in orbit', 'Newton described me with an apple story', 'Einstein explained me as curved spacetime', 'easy', '2026-08-04T00:00:00.000Z'),
('riddle_007', 'subj_nsmq_chemistry', 'Water', 'I am called the universal solvent', 'I have a bent molecular shape', 'I am densest at 4°C', 'My chemical formula has three atoms', 'I am essential for all known life', 'easy', '2026-08-04T00:00:00.000Z'),
('riddle_008', 'subj_nsmq_biology', 'Mitochondria', 'I am known as the powerhouse of the cell', 'I have my own DNA', 'I produce ATP through cellular respiration', 'I have a double membrane', 'I may have once been a free-living bacterium', 'medium', '2026-08-04T00:00:00.000Z'),
('riddle_009', 'subj_nsmq_math', 'Fibonacci sequence', 'I am a sequence where each number is the sum of the two preceding ones', 'I start with 0 and 1', 'I appear in nature in spiral patterns', 'I was introduced to Europe by an Italian mathematician', 'My ratio approaches the golden ratio', 'hard', '2026-08-04T00:00:00.000Z'),
('riddle_010', 'subj_nsmq_physics', 'Photon', 'I am a quantum of light', 'I have no mass but carry energy', 'I travel at the fastest speed possible in the universe', 'Einstein explained the photoelectric effect using me', 'I exhibit wave-particle duality', 'medium', '2026-08-04T00:00:00.000Z')
