('topic_acc_bank', 'subj_wassce_accounting', NULL, 'Bank Reconciliation', 'bank-reconciliation', 'Preparing bank reconciliation statements', NULL, NULL, 6, '2026-08-04T00:00:00.000Z'),
('topic_acc_books', 'subj_wassce_accounting', NULL, 'Books of Original Entry', 'books-original-entry', 'Journals, day books, and recording transactions', NULL, NULL, 2, '2026-08-04T00:00:00.000Z'),
('topic_acc_depreciation', 'subj_wassce_accounting', NULL, 'Depreciation of Assets', 'depreciation', 'Methods of calculating depreciation', NULL, NULL, 7, '2026-08-04T00:00:00.000Z'),
('topic_acc_errors', 'subj_wassce_accounting', NULL, 'Errors and Suspense Accounts', 'errors-suspense', 'Types of errors and correction methods', NULL, NULL, 5, '2026-08-04T00:00:00.000Z'),
('topic_acc_final', 'subj_wassce_accounting', NULL, 'Final Accounts', 'final-accounts', 'Trading, profit and loss accounts, and balance sheets', NULL, NULL, 8, '2026-08-04T00:00:00.000Z'),
('topic_acc_intro', 'subj_wassce_accounting', NULL, 'Introduction to Accounting', 'intro-accounting', 'Basic concepts, principles, and users of accounting information', NULL, NULL, 1, '2026-08-04T00:00:00.000Z'),
('topic_acc_ledger', 'subj_wassce_accounting', NULL, 'Ledger Accounts', 'ledger-accounts', 'Double-entry bookkeeping and posting to ledgers', NULL, NULL, 3, '2026-08-04T00:00:00.000Z'),
('topic_acc_nonprofit', 'subj_wassce_accounting', NULL, 'Non-Profit Organizations', 'nonprofit-accounts', 'Receipts and payments, income and expenditure accounts', NULL, NULL, 10, '2026-08-04T00:00:00.000Z'),
('topic_acc_partnership', 'subj_wassce_accounting', NULL, 'Partnership Accounts', 'partnership-accounts', 'Accounting for partnerships and profit sharing', NULL, NULL, 9, '2026-08-04T00:00:00.000Z'),
('topic_acc_trial', 'subj_wassce_accounting', NULL, 'Trial Balance', 'trial-balance', 'Preparation and purpose of trial balance', NULL, NULL, 4, '2026-08-04T00:00:00.000Z'),
('topic_algebra', 'subj_nsmq_math', NULL, 'Algebra', 'algebra', 'Fundamental algebraic concepts and operations', 'Algebra is the branch of mathematics dealing with symbols and the rules for manipulating those symbols. It includes solving equations, working with polynomials, and understanding functions.', '["ax + b = c → x = (c-b)/a", "(a+b)² = a² + 2ab + b²", "(a-b)² = a² - 2ab + b²", "a² - b² = (a+b)(a-b)"]', 1, '2026-08-04T00:00:00.000Z'),
('topic_atomic', 'subj_nsmq_chemistry', NULL, 'Atomic Structure', 'atomic-structure', 'Structure of atoms and electron configuration', 'Atoms consist of protons, neutrons, and electrons. Understanding electron configuration is key to predicting chemical behavior.', '["Mass number A = Z + N", "E = -13.6/n² eV (hydrogen)", "λ = h/mv (de Broglie)"]', 1, '2026-08-04T00:00:00.000Z'),
