('topic_thermodynamics', 'subj_nsmq_physics', NULL, 'Thermodynamics', 'thermodynamics', 'Study of heat and energy transfer', 'Thermodynamics studies the relationships between heat, work, temperature, and energy in physical systems.', '["Q = mcΔT", "PV = nRT", "W = PΔV", "Efficiency = W/Q_in"]', 4, '2026-08-04T00:00:00.000Z'),
('topic_trigonometry', 'subj_nsmq_math', NULL, 'Trigonometry', 'trigonometry', 'Study of triangles and trigonometric functions', 'Trigonometry studies relationships between side lengths and angles of triangles. The main functions are sine, cosine, and tangent.', '["sin²θ + cos²θ = 1", "tan θ = sin θ / cos θ", "sin 2θ = 2 sin θ cos θ", "cos 2θ = cos²θ - sin²θ"]', 3, '2026-08-04T00:00:00.000Z'),
('topic_twi_composition', 'subj_wassce_twi', NULL, 'Composition', 'composition', 'Writing essays, letters, stories in Twi', NULL, NULL, 4, '2026-08-04T00:00:00.000Z'),
('topic_twi_comprehension', 'subj_wassce_twi', NULL, 'Comprehension', 'comprehension', 'Reading and understanding Twi texts', NULL, NULL, 3, '2026-08-04T00:00:00.000Z'),
('topic_twi_culture', 'subj_wassce_twi', NULL, 'Akan Culture', 'akan-culture', 'Traditions, customs, festivals, naming practices', NULL, NULL, 5, '2026-08-04T00:00:00.000Z'),
('topic_twi_grammar', 'subj_wassce_twi', NULL, 'Twi Grammar', 'twi-grammar', 'Sentence structure, tenses, agreement', NULL, NULL, 1, '2026-08-04T00:00:00.000Z'),
('topic_twi_vocabulary', 'subj_wassce_twi', NULL, 'Twi Vocabulary', 'twi-vocabulary', 'Common words, idioms, proverbs', NULL, NULL, 2, '2026-08-04T00:00:00.000Z'),
('topic_wassce_em_algebra', 'subj_wassce_elect_math', NULL, 'Advanced Algebra', 'advanced-algebra', 'Indices, logarithms, surds, polynomials, and partial fractions', NULL, NULL, 1, '2026-08-04T00:00:00.000Z'),
('topic_wassce_em_coord_geom', 'subj_wassce_elect_math', NULL, 'Coordinate Geometry', 'coordinate-geometry', 'Straight lines, circles, and conic sections', NULL, NULL, 7, '2026-08-04T00:00:00.000Z'),
('topic_wassce_em_differentiation', 'subj_wassce_elect_math', NULL, 'Differentiation', 'differentiation', 'Rules of differentiation and applications', NULL, NULL, 4, '2026-08-04T00:00:00.000Z'),
('topic_wassce_em_integration', 'subj_wassce_elect_math', NULL, 'Integration', 'integration', 'Integration techniques and applications', NULL, NULL, 5, '2026-08-04T00:00:00.000Z'),
