INSERT INTO "flashcards" (id, deck_id, front, back, image_url, hint, difficulty, created_at, updated_at) VALUES
('fc_bio_1', 'deck_biology_terms', 'What organelle is the "powerhouse of the cell"?', 'Mitochondria', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_bio_10', 'deck_biology_terms', 'What is the difference between prokaryotes and eukaryotes?', 'Prokaryotes lack a nucleus; Eukaryotes have a membrane-bound nucleus', NULL, NULL, 2, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_bio_2', 'deck_biology_terms', 'What is the process by which plants make food?', 'Photosynthesis: 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_bio_3', 'deck_biology_terms', 'What are the four DNA nucleotide bases?', 'Adenine (A), Thymine (T), Guanine (G), Cytosine (C)', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_bio_4', 'deck_biology_terms', 'What is the central dogma of molecular biology?', 'DNA → RNA → Protein (Transcription → Translation)', NULL, NULL, 2, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_bio_5', 'deck_biology_terms', 'What is the function of ribosomes?', 'Protein synthesis', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_bio_6', 'deck_biology_terms', 'What is ATP?', 'Adenosine Triphosphate - the energy currency of cells', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_bio_7', 'deck_biology_terms', 'What is osmosis?', 'Movement of water from high to low concentration through a semi-permeable membrane', NULL, NULL, 2, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_bio_8', 'deck_biology_terms', 'What are the phases of mitosis?', 'PMAT: Prophase, Metaphase, Anaphase, Telophase', NULL, NULL, 2, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_bio_9', 'deck_biology_terms', 'What is the function of the cell membrane?', 'Controls what enters and exits the cell (selectively permeable)', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_chem_1', 'deck_chemistry_formulas', 'What is Avogadro''s number?', '6.02 × 10²³ mol⁻¹', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_chem_10', 'deck_chemistry_formulas', 'What is the molar mass of H₂SO₄?', '98 g/mol', NULL, NULL, 2, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_chem_2', 'deck_chemistry_formulas', 'What is the molar gas volume at STP?', '22.4 L/mol', NULL, NULL, 2, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_chem_3', 'deck_chemistry_formulas', 'What is the formula for moles?', 'n = mass/molar mass', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_chem_4', 'deck_chemistry_formulas', 'What is the pH formula?', 'pH = -log[H⁺]', NULL, NULL, 2, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_chem_5', 'deck_chemistry_formulas', 'What is the ideal gas constant R?', '8.314 J/(mol·K) or 0.0821 L·atm/(mol·K)', NULL, NULL, 3, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_chem_6', 'deck_chemistry_formulas', 'What is the molecular formula for water?', 'H₂O', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_chem_7', 'deck_chemistry_formulas', 'What is the atomic number of carbon?', '6', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_chem_8', 'deck_chemistry_formulas', 'What is the concentration formula?', 'C = n/V (moles per liter)', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_chem_9', 'deck_chemistry_formulas', 'What is the electron configuration of oxygen?', '1s² 2s² 2p⁴ or [He] 2s² 2p⁴', NULL, NULL, 2, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_math_1', 'deck_math_formulas', 'What is the quadratic formula?', 'x = (-b ± √(b²-4ac)) / 2a', NULL, NULL, 2, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_math_10', 'deck_math_formulas', 'What is the slope-intercept form of a line?', 'y = mx + b', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_math_2', 'deck_math_formulas', 'What is the formula for the area of a circle?', 'A = πr²', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_math_3', 'deck_math_formulas', 'What is the Pythagorean theorem?', 'a² + b² = c²', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_math_4', 'deck_math_formulas', 'What is the formula for compound interest?', 'A = P(1 + r/n)^(nt)', NULL, NULL, 3, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_math_5', 'deck_math_formulas', 'What is the distance formula between two points?', 'd = √[(x₂-x₁)² + (y₂-y₁)²]', NULL, NULL, 2, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_math_6', 'deck_math_formulas', 'What is the sum of angles in a triangle?', '180°', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_math_7', 'deck_math_formulas', 'What is the formula for the volume of a sphere?', 'V = (4/3)πr³', NULL, NULL, 2, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_math_8', 'deck_math_formulas', 'What is sin²θ + cos²θ equal to?', '1 (Pythagorean identity)', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_math_9', 'deck_math_formulas', 'What is the derivative of xⁿ?', 'nxⁿ⁻¹ (Power rule)', NULL, NULL, 3, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_phys_1', 'deck_physics_formulas', 'What is Newton''s Second Law?', 'F = ma (Force = mass × acceleration)', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_phys_10', 'deck_physics_formulas', 'What is the ideal gas equation?', 'PV = nRT', NULL, NULL, 2, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_phys_2', 'deck_physics_formulas', 'What is the formula for kinetic energy?', 'KE = ½mv²', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_phys_3', 'deck_physics_formulas', 'What is the formula for potential energy?', 'PE = mgh', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_phys_4', 'deck_physics_formulas', 'What is Ohm''s Law?', 'V = IR (Voltage = Current × Resistance)', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_phys_5', 'deck_physics_formulas', 'What is the speed of light?', 'c = 3 × 10⁸ m/s', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_phys_6', 'deck_physics_formulas', 'What is the formula for momentum?', 'p = mv', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_phys_7', 'deck_physics_formulas', 'What is the formula for work done?', 'W = Fd cos θ', NULL, NULL, 2, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_phys_8', 'deck_physics_formulas', 'What is the equation for wave speed?', 'v = fλ (speed = frequency × wavelength)', NULL, NULL, 2, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('fc_phys_9', 'deck_physics_formulas', 'What is the acceleration due to gravity on Earth?', 'g ≈ 9.8 m/s² or 10 m/s²', NULL, NULL, 1, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z')
