INSERT INTO "questions" (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id, created_at, updated_at) VALUES
('nsmq_bio_pod_001', NULL, 'subj_wassce_biology', NULL, NULL, NULL, 'If a cell has 46 chromosomes, how many chromosomes will be in the gametes after meiosis?', 'problem', 'problem_of_day', NULL, '23', 'Meiosis reduces chromosome number by half: 46/2 = 23', 'easy', 5, 1, 120, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('nsmq_bio_pod_002', NULL, 'subj_wassce_biology', NULL, NULL, NULL, 'In a cross between Tt × Tt (T = tall, t = short), what percentage of offspring will be tall?', 'problem', 'problem_of_day', NULL, '75%', 'Punnett square: TT, Tt, Tt, tt. Tall (T_) = 3/4 = 75%', 'medium', 5, 1, 120, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('nsmq_bio_pod_003', NULL, 'subj_wassce_biology', NULL, NULL, NULL, 'If a DNA strand has 20% adenine, what percentage is cytosine?', 'problem', 'problem_of_day', NULL, '30%', 'A=T=20%, so A+T=40%. C+G=60%, C=G=30%', 'medium', 5, 1, 120, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('nsmq_bio_pod_004', NULL, 'subj_wassce_biology', NULL, NULL, NULL, 'A gene codes for a protein with 150 amino acids. How many nucleotides are in the mRNA (excluding stop codon)?', 'problem', 'problem_of_day', NULL, '450', 'Each amino acid needs 3 nucleotides (codon): 150 × 3 = 450', 'medium', 5, 1, 120, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('nsmq_bio_pod_005', NULL, 'subj_wassce_biology', NULL, NULL, NULL, 'If the cardiac output is 5 L/min and the stroke volume is 70 mL, what is the heart rate?', 'problem', 'problem_of_day', NULL, '71 beats/min', 'CO = SV × HR. HR = 5000/70 ≈ 71 beats/min', 'hard', 5, 1, 120, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('nsmq_bio_pod_006', NULL, 'subj_wassce_biology', NULL, NULL, NULL, 'In a population of 1000 individuals, 360 show the recessive phenotype. What is the frequency of the dominant allele?', 'problem', 'problem_of_day', NULL, '0.4', 'q² = 360/1000 = 0.36, q = 0.6. p = 1 - 0.6 = 0.4', 'hard', 5, 1, 120, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('nsmq_bio_pod_007', NULL, 'subj_wassce_biology', NULL, NULL, NULL, 'How many ATP molecules are produced from one glucose molecule in complete aerobic respiration?', 'problem', 'problem_of_day', NULL, '36-38', 'Glycolysis: 2, Krebs: 2, ETC: 32-34. Total: 36-38 ATP', 'hard', 5, 1, 120, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('nsmq_bio_pod_008', NULL, 'subj_wassce_biology', NULL, NULL, NULL, 'A man with blood type A (heterozygous) marries a woman with blood type B (heterozygous). What is the probability of their child having blood type O?', 'problem', 'problem_of_day', NULL, '25%', 'IAi × IBi. Offspring: IAIB, IAi, IBi, ii. Type O (ii) = 1/4 = 25%', 'hard', 5, 1, 120, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('nsmq_bio_pod_009', NULL, 'subj_wassce_biology', NULL, NULL, NULL, 'If a food chain has 1000 kcal at the producer level, how much energy is available to the tertiary consumer?', 'problem', 'problem_of_day', NULL, '1 kcal', '10% rule: 1000 → 100 → 10 → 1 kcal', 'medium', 5, 1, 120, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('nsmq_bio_pod_010', NULL, 'subj_wassce_biology', NULL, NULL, NULL, 'A cell undergoes 5 rounds of mitosis. How many cells result?', 'problem', 'problem_of_day', NULL, '32', '2⁵ = 32 cells', 'easy', 5, 1, 120, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('nsmq_bio_pod_011', NULL, 'subj_wassce_biology', NULL, NULL, NULL, 'If the DNA template strand is 3''-TACGGT-5'', what is the mRNA sequence?', 'problem', 'problem_of_day', NULL, '5''-AUGCCA-3''', 'mRNA is complementary to template: A→U, T→A, C→G, G→C', 'medium', 5, 1, 120, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('nsmq_bio_pod_012', NULL, 'subj_wassce_biology', NULL, NULL, NULL, 'Calculate the water potential if solute potential is -0.5 MPa and pressure potential is 0.3 MPa.', 'problem', 'problem_of_day', NULL, '-0.2 MPa', 'Ψ = Ψs + Ψp = -0.5 + 0.3 = -0.2 MPa', 'hard', 5, 1, 120, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
