('q_acc_bank_004', 'topic_acc_bank', 'subj_wassce_accounting', NULL, NULL, NULL, 'Uncredited deposits are:', 'multiple_choice', NULL, '["Cheques issued but not cleared","Deposits made but not yet reflected in bank statement","Bank charges","Standing orders"]', 'B', 'Uncredited deposits (also called deposits in transit) are deposits made but not yet appearing in the bank statement.', 'medium', 3, 1, 30, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_acc_bank_005', 'topic_acc_bank', 'subj_wassce_accounting', NULL, NULL, NULL, 'When preparing a bank reconciliation, bank charges should be:', 'multiple_choice', NULL, '["Added to cash book balance","Deducted from cash book balance","Added to bank statement balance","Ignored"]', 'B', 'Bank charges reduce the cash book balance when updating it to agree with the bank statement.', 'medium', 3, 1, 30, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
