('q_bece_math_2023_006', NULL, 'subj_bece_math', 'exam_bece', 'paper_bece_1', 'pp_bece_math_2023_1', 'Write 0.7 as a fraction.', 'multiple_choice', NULL, '["A. 7/100", "B. 7/10", "C. 70/10", "D. 7/1"]', 'B', '0.7 = 7/10.', 'easy', 3, 1, 30, 6, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2023_007', NULL, 'subj_bece_math', 'exam_bece', 'paper_bece_1', 'pp_bece_math_2023_1', 'The HCF of 8 and 12 is:', 'multiple_choice', NULL, '["A. 2", "B. 4", "C. 8", "D. 24"]', 'B', 'HCF of 8 and 12 is 4.', 'easy', 3, 1, 30, 7, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
