('q_bece_math_2024_21', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'Find the area of a rectangle with length 8 cm and width 5 cm.', 'multiple_choice', NULL, '["A. 13 cm²", "B. 26 cm²", "C. 40 cm²", "D. 80 cm²"]', 'C', 'Area = length × width = 8 × 5 = 40 cm²', 'easy', 1, 1, 60, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_22', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'What is the perimeter of a square with side 7 cm?', 'multiple_choice', NULL, '["A. 14 cm", "B. 21 cm", "C. 28 cm", "D. 49 cm"]', 'C', 'Perimeter = 4 × side = 4 × 7 = 28 cm', 'easy', 1, 1, 60, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_23', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'The angles in a triangle add up to:', 'multiple_choice', NULL, '["A. 90°", "B. 180°", "C. 270°", "D. 360°"]', 'B', 'The sum of angles in any triangle is 180°', 'easy', 1, 1, 60, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_24', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'Find the circumference of a circle with radius 7 cm. (Take π = 22/7)', 'multiple_choice', NULL, '["A. 22 cm", "B. 44 cm", "C. 154 cm", "D. 14 cm"]', 'B', 'C = 2πr = 2 × 22/7 × 7 = 44 cm', 'medium', 1, 1, 90, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_25', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'What type of angle is 135°?', 'multiple_choice', NULL, '["A. Acute", "B. Right", "C. Obtuse", "D. Reflex"]', 'C', 'Obtuse angles are between 90° and 180°', 'easy', 1, 1, 60, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_26', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'Find the volume of a cube with side 4 cm.', 'multiple_choice', NULL, '["A. 12 cm³", "B. 16 cm³", "C. 48 cm³", "D. 64 cm³"]', 'D', 'Volume = side³ = 4³ = 64 cm³', 'medium', 1, 1, 60, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_27', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'Two angles that add up to 180° are called:', 'multiple_choice', NULL, '["A. Complementary", "B. Supplementary", "C. Alternate", "D. Corresponding"]', 'B', 'Supplementary angles sum to 180°', 'easy', 1, 1, 60, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_28', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'Find the area of a triangle with base 10 cm and height 6 cm.', 'multiple_choice', NULL, '["A. 16 cm²", "B. 30 cm²", "C. 60 cm²", "D. 80 cm²"]', 'B', 'Area = ½ × base × height = ½ × 10 × 6 = 30 cm²', 'medium', 1, 1, 60, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_29', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'How many faces does a cuboid have?', 'multiple_choice', NULL, '["A. 4", "B. 6", "C. 8", "D. 12"]', 'B', 'A cuboid has 6 faces', 'easy', 1, 1, 60, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_30', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'Convert 2.5 km to metres.', 'multiple_choice', NULL, '["A. 250 m", "B. 2500 m", "C. 25 m", "D. 25000 m"]', 'B', '1 km = 1000 m, so 2.5 km = 2500 m', 'easy', 1, 1, 60, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_31', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'Find the mean of: 4, 6, 8, 10, 12', 'multiple_choice', NULL, '["A. 6", "B. 8", "C. 10", "D. 40"]', 'B', 'Mean = (4+6+8+10+12)/5 = 40/5 = 8', 'easy', 1, 1, 60, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_32', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'What is the mode of: 2, 3, 3, 4, 5, 3, 6?', 'multiple_choice', NULL, '["A. 2", "B. 3", "C. 4", "D. 5"]', 'B', 'Mode is the most frequent value. 3 appears 3 times.', 'easy', 1, 1, 60, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_33', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'Find the median of: 3, 7, 2, 9, 5', 'multiple_choice', NULL, '["A. 2", "B. 5", "C. 7", "D. 9"]', 'B', 'Arranged: 2,3,5,7,9. Middle value is 5.', 'medium', 1, 1, 90, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_34', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'A coin is tossed. What is the probability of getting a head?', 'multiple_choice', NULL, '["A. 0", "B. 1/4", "C. 1/2", "D. 1"]', 'C', 'P(Head) = 1/2 (one favorable outcome out of two)', 'easy', 1, 1, 60, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_35', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'Find the range of: 15, 22, 8, 30, 12', 'multiple_choice', NULL, '["A. 8", "B. 15", "C. 22", "D. 30"]', 'C', 'Range = Highest - Lowest = 30 - 8 = 22', 'easy', 1, 1, 60, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_36', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'A die is rolled. What is the probability of getting a number greater than 4?', 'multiple_choice', NULL, '["A. 1/6", "B. 2/6", "C. 3/6", "D. 4/6"]', 'B', 'Numbers greater than 4: 5,6. P = 2/6 = 1/3', 'medium', 1, 1, 90, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_37', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'In a class of 30 students, 18 are girls. What fraction are boys?', 'multiple_choice', NULL, '["A. 3/5", "B. 2/5", "C. 18/30", "D. 12/18"]', 'B', 'Boys = 30 - 18 = 12. Fraction = 12/30 = 2/5', 'easy', 1, 1, 60, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_38', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'A bag contains 3 red, 4 blue, and 5 green balls. What is the probability of picking a blue ball?', 'multiple_choice', NULL, '["A. 1/3", "B. 4/12", "C. 5/12", "D. 3/12"]', 'B', 'Total = 12. P(blue) = 4/12 = 1/3', 'medium', 1, 1, 90, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_39', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'If 40% of students passed an exam, what percentage failed?', 'multiple_choice', NULL, '["A. 40%", "B. 50%", "C. 60%", "D. 100%"]', 'C', 'Failed = 100% - 40% = 60%', 'easy', 1, 1, 60, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_math_2024_40', NULL, 'subj_bece_math', NULL, NULL, 'pp_bece_math_2024_1', 'A pie chart shows 90° for "Football". What fraction does this represent?', 'multiple_choice', NULL, '["A. 1/2", "B. 1/3", "C. 1/4", "D. 1/5"]', 'C', '90°/360° = 1/4', 'medium', 1, 1, 90, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_num_001', NULL, 'subj_bece_math', NULL, NULL, NULL, 'What is 3/4 expressed as a percentage?', 'multiple_choice', NULL, '["25%","50%","75%","80%"]', '75%', '3/4 = 0.75 = 75%. Multiply fraction by 100.', 'easy', 3, 1, 30, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_num_002', NULL, 'subj_bece_math', NULL, NULL, NULL, 'Find the LCM of 12 and 18:', 'multiple_choice', NULL, '["6","36","72","216"]', 'B', 'LCM(12,18) = 36. The smallest number divisible by both 12 and 18.', 'medium', 3, 1, 30, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_num_003', NULL, 'subj_bece_math', NULL, NULL, NULL, 'Round 3,847 to the nearest hundred:', 'multiple_choice', NULL, '["3,800","3,850","3,900","4,000"]', '3,800', '3,847 rounds down to 3,800 (47 < 50).', 'easy', 3, 1, 30, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_bece_num_004', NULL, 'subj_bece_math', NULL, NULL, NULL, 'What is 15% of 200?', 'multiple_choice', NULL, '["15","30","45","300"]', 'B', '15% of 200 = 0.15 × 200 = 30.', 'easy', 3, 1, 30, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
