('q_crs_kings_002', 'topic_crs_kings', 'subj_wassce_crs', NULL, NULL, NULL, 'King Solomon was known for his:', 'multiple_choice', NULL, '["Military conquests","Wisdom","Prophecies","Miracles"]', 'Wisdom', 'Solomon was renowned for his wisdom, granted by God (1 Kings 3).', 'easy', 3, 1, 30, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_crs_kings_003', 'topic_crs_kings', 'subj_wassce_crs', NULL, NULL, NULL, 'Elijah challenged the prophets of Baal on:', 'multiple_choice', NULL, '["Mount Sinai","Mount Carmel","Mount Zion","Mount Nebo"]', 'Mount Carmel', 'Elijah''s confrontation with Baal''s prophets occurred on Mount Carmel (1 Kings 18).', 'medium', 3, 1, 30, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_crs_kings_004', 'topic_crs_kings', 'subj_wassce_crs', NULL, NULL, NULL, 'The prophet who was swallowed by a great fish was:', 'multiple_choice', NULL, '["Elijah","Elisha","Jonah","Isaiah"]', 'Jonah', 'Jonah was swallowed by a great fish when fleeing from God''s call (Jonah 1-2).', 'easy', 3, 1, 30, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_crs_kings_005', 'topic_crs_kings', 'subj_wassce_crs', NULL, NULL, NULL, 'David killed Goliath with:', 'multiple_choice', NULL, '["A sword","A spear","A sling and stone","An arrow"]', 'C', 'David defeated Goliath with a sling and stone (1 Samuel 17).', 'easy', 3, 1, 30, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
