('q_lit_devices_003', 'topic_lit_devices', 'subj_wassce_literature', NULL, NULL, NULL, 'What is personification?', 'multiple_choice', NULL, '["A comparison using like or as","Giving human qualities to non-human things","Exaggeration for effect","A play on words"]', 'Giving human qualities to non-human things', 'Personification attributes human characteristics to animals, objects, or abstract concepts.', 'easy', 3, 1, 30, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_lit_devices_004', 'topic_lit_devices', 'subj_wassce_literature', NULL, NULL, NULL, 'Which literary device is used in "The wind whispered through the trees"?', 'multiple_choice', NULL, '["Simile","Metaphor","Personification","Hyperbole"]', 'Personification', 'Personification is used because the wind is given the human ability to whisper.', 'medium', 3, 1, 30, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
('q_lit_devices_005', 'topic_lit_devices', 'subj_wassce_literature', NULL, NULL, NULL, 'What is an oxymoron?', 'multiple_choice', NULL, '["A figure of speech combining contradictory terms","A comparison without using like or as","An extreme exaggeration","A reference to another work"]', 'A figure of speech combining contradictory terms', 'An oxymoron places contradictory terms side by side, like "deafening silence" or "living dead".', 'medium', 3, 1, 30, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04T00:00:00.000Z', '2026-08-04T00:00:00.000Z'),
